#import "TFAISessionFilePaths.h"
static NSDictionary *SFLocal(NSString *path,NSString *label){BOOL folder=NO;if(!path.length||!SFInside(path.stringByDeletingLastPathComponent,path)||![NSFileManager.defaultManager fileExistsAtPath:path isDirectory:&folder])return nil;return @{@"name":label.length?label:path.lastPathComponent,@"localPath":path,@"accessBoundary":path.stringByDeletingLastPathComponent.stringByResolvingSymlinksInPath,@"folder":@(folder),@"bytes":@([[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil][NSFileSize] unsignedLongLongValue])};}
// The table owns header width; lay out segments from its final bounds, not a
