 if(directory){if(SFInside(boundary,directory))for(NSString *name in [NSFileManager.defaultManager contentsOfDirectoryAtPath:directory error:nil]){if([name hasPrefix:@"."])continue;NSString *path=SFPath(boundary,[[directory stringByAppendingPathComponent:name] substringFromIndex:boundary.length+1]);if(path){origin=self.sourceMessageID?:@"";add(SFLocal(path,TFAIAttachmentFolderName(path)));}}}
