 NSUInteger index=0;for(NSDictionary *image in message[@"images"]){index++;add(@{@"name":[NSString stringWithFormat:@"图片 %lu",(unsigned long)index],@"category":@"图片",@"previewItem":@{@"kind":@"image",@"data":image[@"data"]?:@""}});}}
