- (void)categoryChanged{NSArray *values=@[@"",@"附件",@"生成",@"头文件",@"构建",@"项目"];self.category=values[self.categories.selectedSegmentIndex];[self updateSearchResultsForSearchController:self.navigationItem.searchController];}
- (void)updateSearchResultsForSearchController:(UISearchController *)search{NSString *query=search.searchBar.text?:@"";self.filtered=[self.items filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *item,NSDictionary *bindings){BOOL category=!self.category.length||[item[@"source"] isEqual:self.category];NSString *text=[NSString stringWithFormat:@"%@ %@ %@",item[@"name"]?:@"",item[@"category"]?:@"",item[@"source"]?:@""];return category&&(!query.length||[text localizedCaseInsensitiveContainsString:query]);}]];UILabel *empty=[UILabel new];empty.text=@"暂无匹配的会话文件";empty.textAlignment=NSTextAlignmentCenter;empty.textColor=UIColor.secondaryLabelColor;self.tableView.backgroundView=self.filtered.count?nil:empty;[self.tableView reloadData];}
- (NSInteger)tableView:(UITableView *)table numberOfRowsInSection:(NSInteger)section{return self.filtered.count;}
- (UITableViewCell *)tableView:(UITableView *)table cellForRowAtIndexPath:(NSIndexPath *)index{NSDictionary *item=self.filtered[index.row];NSString *path=item[@"localPath"];NSString *kind=item[@"category"]?:@"文件";NSString *size=[item[@"folder"] boolValue]?@"文件夹":[NSByteCountFormatter stringFromByteCount:[item[@"bytes"] longLongValue] countStyle:NSByteCountFormatterCountStyleFile];NSString *detail=path.length?[NSString stringWithFormat:@"%@ · %@",kind,size]:kind;UITableViewCell *cell=AICell(item[@"name"],detail,([item[@"folder"] boolValue]||item[@"previewItem"][@"directoryGrant"])?@"folder":@"doc");cell.textLabel.numberOfLines=2;cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return cell;}
- (NSString *)tableView:(UITableView *)table titleForFooterInSection:(NSInteger)section{return @"仅在本机浏览，不会自动发送给模型。文件保留在原目录；已移除的文件需重新导入。";}
- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)index{[table deselectRowAtIndexPath:index animated:YES];NSDictionary *item=self.filtered[index.row];if(self.directoryGrant){NSError *error=nil;if(!TFAIReadDirectoryReference(self.directoryGrant,@{@"action":@"validate"},&error)){AIAlert(self,@"目录不可访问",error.localizedDescription);return;}}NSDictionary *grant=item[@"previewItem"][@"directoryGrant"]?item[@"previewItem"]:nil;if(grant){NSError *error=nil;NSURL *url=TFAIDirectoryBrowserURL(grant,&error);if(!url){AIAlert(self,@"目录不可访问",error.localizedDescription);return;}TFAISessionFiles *child=[[TFAISessionFiles alloc]initWithStyle:UITableViewStyleInsetGrouped];child.directory=url.path;child.boundary=url.path;child.directoryGrant=grant;child.scopedURL=url;child.scopedAccess=[url startAccessingSecurityScopedResource];child.locateMessage=self.locateMessage;child.sourceMessageID=item[@"messageID"];[self.navigationController pushViewController:child animated:YES];return;}NSString *path=item[@"localPath"];if(path.length&&!SFInside(item[@"accessBoundary"],path)){AIAlert(self,@"文件已变化",@"请重新导入或生成文件。");return;}if([item[@"folder"] boolValue]){TFAISessionFiles *child=[[TFAISessionFiles alloc]initWithStyle:UITableViewStyleInsetGrouped];child.directory=path;child.directoryGrant=self.directoryGrant;child.boundary=self.boundary?:path;child.locateMessage=self.locateMessage;child.sourceMessageID=item[@"messageID"]?:self.sourceMessageID;[self.navigationController pushViewController:child animated:YES];return;}if(item[@"previewItem"]&&!path.length){[self.navigationController pushViewController:TFAISentAttachmentPreview(item[@"previewItem"]) animated:YES];return;}NSDictionary *attrs=[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil];if(![attrs[NSFileType] isEqual:NSFileTypeRegular]){AIAlert(self,@"文件已移除",@"请重新生成或导入。");return;}if([attrs[NSFileSize] unsignedLongLongValue]<=2*1024*1024){NSString *text=[NSString stringWithContentsOfFile:path encoding:N