UIViewController *TFAISessionFilesController(NSDictionary *session,NSString *projectRoot){TFAISessionFiles *view=[[TFAISessionFiles alloc]initWithStyle:UITableViewStyleInsetGrouped];view.session=session;view.projectRoot=projectRoot;return view;}

UIViewController *TFAISessionFilesControllerWithNavigation(NSDictionary *session,NSString *projectRoot,void (^locateMessage)(NSString *messageID)){TFAISessionFiles *view=(id)TFAISessionFilesController(session,projectRoot);view.locateMessage=locateMessage;return view;}
